export function searchFoods(query: string): FoodItem[] {
  if (!query.trim()) return foodDatabase;
  const q = query.toLowerCase();
  return foodDatabase.filter(f => f.name.toLowerCase().includes(q));
}
export function getFoodByName(name: string): FoodItem | undefined {
  return foodDatabase.find(f => f.name === name || name.includes(f.name));
}
